  "vocab-127": {"promptNative":"Vocês vêm? (informal)","options":["✓ correto — 'vous autres' quebequense + pergunta com '-tu'","gramaticalmente incorreto","significa \"vocês outros, estão sozinhos?\"","registro formal"],"distractorNotes":{"gramaticalmente incorreto":{"pt":"ambos os traços são quebequense informal padrão."},"significa \"vocês outros, estão sozinhos?\"":{"pt":"não — 'vous autres' só enfatiza 'vocês', e '-tu' é marca de pergunta."},"registro formal":{"pt":"pelo contrário — é francês falado informal."}}},
