  "vocab-129": {"promptNative":"Dei o livro a ele. (informal)","options":["✓ quebequense informal correto — 'y' por 'lui'","gramaticalmente incorreto","significa \"dei o livro ali\"","significa \"dei o livro a isso\" (objeto)"],"distractorNotes":{"gramaticalmente incorreto":{"pt":"é um traço falado muito enraizado no Quebec."},"significa \"dei o livro ali\"":{"pt":"esse é o sentido padrão de 'y' (lá); aqui substitui 'lui' (lhe)."},"significa \"dei o livro a isso\" (objeto)":{"pt":"não — 'y' é o objeto indireto 'le', não um objeto direto."}}},
  "vocab-130": {"promptNative":"Quando você chegar, vamos jantar. (informal)","options":["✓ quebequense informal correto — 'que' depois de 'quand'","gramaticalmente incorreto","significa \"quando quer que chegue\"","registro formal"],"distractorNotes":{"gramaticalmente incorreto":{"pt":"é um padrão informal quebequense reconhecido."},"significa \"quando quer que chegue\"":{"pt":"não — só significa 'quando chegar'; 'que' não adiciona o sentido de 'sempre que'."},"registro formal":{"pt":"pelo contrário — o francês padrão/formal omite o 'que'."}}},
